CREATE TABLE IF NOT EXISTS game_cards(id TEXT PRIMARY KEY,data JSONB NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS card_classes(id TEXT PRIMARY KEY,data JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS shop_packages(id TEXT PRIMARY KEY,data JSONB NOT NULL,version BIGINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS wallets(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,coins INTEGER NOT NULL DEFAULT 2000 CHECK(coins>=0));
CREATE TABLE IF NOT EXISTS card_inventory(user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,card_id TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),PRIMARY KEY(user_id,card_id));
CREATE TABLE IF NOT EXISTS pack_draws(user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,request_id TEXT NOT NULL,result JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(user_id,request_id));
CREATE TABLE IF NOT EXISTS admin_changes(id BIGSERIAL PRIMARY KEY,admin_id BIGINT REFERENCES admins(id),action TEXT NOT NULL,target TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS league_seasons(user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,season_id TEXT NOT NULL,meta JSONB NOT NULL,results JSONB,settlement JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),finished_at TIMESTAMPTZ,PRIMARY KEY(user_id,season_id));

CREATE TABLE IF NOT EXISTS economy_campaigns(id TEXT PRIMARY KEY,result JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS coin_awards(campaign_id TEXT NOT NULL REFERENCES economy_campaigns(id),user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,amount INTEGER NOT NULL CHECK(amount>0),PRIMARY KEY(campaign_id,user_id));
ALTER TABLE wallets ALTER COLUMN coins SET DEFAULT 2000;
CREATE TABLE IF NOT EXISTS collection_rewards(user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,reward_id TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),claimed_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(user_id,reward_id));
